    }

    // 按倍率分组，记录每个倍率对应的最大和最小基础分
    const int MAX_V = 1000;
    const long long INF = 1e9;
    vector<long long> min_base(MAX_V + 1, INF);
    vector<long long> max_base(MAX_V + 1, -INF);

    for (int i = 0; i < n; ++i) {
        int m = mult[i];
        long long b = base[i];
        if (b < min_base[m]) min_base[m] = b;
        if (b > max_base[m]) max_base[m] = b;
    }

    // 枚举倍率对，计算最大增益
    long long max_gain = 0;  // 可以不交换
    for (int ci = 1; ci <= MAX_V; ++ci) {
        if (min_base[ci] == INF) continue;
        for (int cj = ci; cj <= MAX_V; ++cj) {
            if (max_base[cj] == -INF) continue;
            long long gain = (max_base[cj] - min_base[ci]) * (cj - ci);
            if (gain > max_gain) {
                max_gain = gain;
            }
        }
    }

    cout << original + max_gain << '\n';
    return 0;
}
